<?php
declare(strict_types=1);
require_once __DIR__.'/bootstrap.php';
$uid=saas_require_login();$db=saas_db();$slug=preg_replace('/[^a-z0-9-]/','',strtolower((string)($_GET['plan']??'pro')));$s=$db->prepare('SELECT * FROM saas_plans WHERE slug=? AND active=1 LIMIT 1');$s->execute([$slug]);$plan=$s->fetch(PDO::FETCH_ASSOC);if(!$plan||$plan['slug']==='free'){$plan=$db->query("SELECT * FROM saas_plans WHERE slug='pro' LIMIT 1")->fetch(PDO::FETCH_ASSOC);}
$key=defined('RAZORPAY_KEY_ID')?RAZORPAY_KEY_ID:'';$secret=defined('RAZORPAY_KEY_SECRET')?RAZORPAY_KEY_SECRET:'';$error='';$success='';$order=null;
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['verify_payment'])){ $oid=trim((string)($_POST['razorpay_order_id']??''));$pid=trim((string)($_POST['razorpay_payment_id']??''));$sig=trim((string)($_POST['razorpay_signature']??''));$expected=hash_hmac('sha256',$oid.'|'.$pid,$secret);if($oid===''||$pid===''||$sig===''||$secret===''||!hash_equals($expected,$sig)){$error='Payment verification failed.';}else{$o=$db->prepare('SELECT * FROM saas_orders WHERE gateway_order_id=? AND user_id=? LIMIT 1');$o->execute([$oid,$uid]);$row=$o->fetch(PDO::FETCH_ASSOC);if(!$row||$row['status']==='paid'){$error=$row?'Payment already processed.':'Order not found.';}else{$db->beginTransaction();try{$db->prepare("UPDATE saas_orders SET status='paid',paid_at=NOW() WHERE id=?")->execute([$row['id']]);$db->prepare("UPDATE creator_users SET plan=?,credits=credits+? WHERE id=?")->execute([$row['plan_slug'],(int)$plan['monthly_credits'],$uid]);$db->prepare("INSERT INTO saas_subscriptions(user_id,plan_slug,status,order_id,starts_at,ends_at) VALUES(?,?, 'active',?,NOW(),DATE_ADD(NOW(),INTERVAL 1 MONTH))")->execute([$uid,$row['plan_slug'],$oid]);$ref=$db->prepare('SELECT * FROM saas_referrals WHERE referred_id=? LIMIT 1');$ref->execute([$uid]);$rr=$ref->fetch(PDO::FETCH_ASSOC);if($rr){$commission=round((float)$row['amount_inr']*((float)$rr['commission_percent']/100),2);$db->prepare('INSERT IGNORE INTO saas_wallets(user_id,balance_inr) VALUES(?,0)')->execute([$rr['referrer_id']]);$w=$db->prepare('SELECT balance_inr FROM saas_wallets WHERE user_id=? FOR UPDATE');$w->execute([$rr['referrer_id']]);$bal=(float)$w->fetchColumn()+$commission;$db->prepare('UPDATE saas_wallets SET balance_inr=? WHERE user_id=?')->execute([$bal,$rr['referrer_id']]);$db->prepare('UPDATE saas_referrals SET commission_inr=commission_inr+? WHERE id=?')->execute([$commission,$rr['id']]);$db->prepare('INSERT INTO saas_wallet_transactions(user_id,type,amount_inr,balance_after,reference_id,description) VALUES(?,?,?,?,?,?)')->execute([$rr['referrer_id'],'referral',$commission,$bal,$oid,'Referral commission']);}$db->commit();$success='Payment verified. Your '.$plan['name'].' plan is active.';}catch(Throwable $e){if($db->inTransaction())$db->rollBack();$error='Could not activate the plan.';error_log($e->getMessage());}}}}
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['create_order'])){if($key===''||$secret===''||str_starts_with($key,'YOUR_')||str_starts_with($secret,'YOUR_')){$error='Razorpay keys are not configured yet.';}else{$amount=(int)round((float)$plan['price_inr']*100);$payload=json_encode(['amount'=>$amount,'currency'=>'INR','receipt'=>'st_'.bin2hex(random_bytes(6)),'notes'=>['user_id'=>(string)$uid,'plan'=>$plan['slug']]]);$ch=curl_init('https://api.razorpay.com/v1/orders');curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>$payload,CURLOPT_USERPWD=>$key.':'.$secret,CURLOPT_HTTPHEADER=>['Content-Type: application/json']]);$raw=curl_exec($ch);$http=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);$r=json_decode((string)$raw,true);if($http>=200&&$http<300&&!empty($r['id'])){$db->prepare('INSERT INTO saas_orders(user_id,plan_slug,amount_inr,gateway_order_id,status) VALUES(?,?,?,?,?)')->execute([$uid,$plan['slug'],$plan['price_inr'],$r['id'],'created']);$order=$r;}else{$error='Unable to create payment order.';}}}
require_once __DIR__.'/../header.php';
