ment.getElementById('pay').onclick=()=>{const o=new Razorpay({key:<?=json_encode($key)?>,amount:<?=json_encode((int)round((float)$plan['price_inr']*100))?>,currency:'INR',name:'SmartToolz',description:<?=json_encode($plan['name'].' Monthly Plan')?>,order_id:<?=json_encode($order['id'])?>,handler:r=>{oid.value=r.razorpay_order_id;pid.value=r.razorpay_payment_id;sig.value=r.razorpay_signature;document.getElementById('verify').submit()}});o.open()};</script><?php else:?><form method="post"><input type="hidden" name="create_order" value="1"><button class="btn" type="submit">Start secure payment</button></form><?php endif;?><p class="muted" style="font-size:12px;margin-top:20px">Payments are verified server-side. Never place a Razorpay secret in frontend JavaScript.</p></section></main><?php require_once __DIR__.'/../footer.php'; ?></body></html>
